-- Local proof for 20261011_000916_created_by_requires_membership.sql and its
-- rollback. Empty Postgres only (never production). Refuses to run when
-- public.organizations already exists. One transaction, ends in ROLLBACK.
--
--   createdb created_by_proof
--   psql "postgresql:///created_by_proof" -v ON_ERROR_STOP=1 \
--     -f web/supabase/tests/20261011_created_by_requires_membership.sql
--
-- Run psql from the repo root so the \i paths resolve.
-- The fixture uses the live (2026-10-11) definitions of every function and
-- policy involved, pulled with pg_get_functiondef / pg_policies.

\set ON_ERROR_STOP on

DO $$
BEGIN
  IF to_regclass('public.organizations') IS NOT NULL THEN
    RAISE EXCEPTION 'refusing to run: public.organizations already exists';
  END IF;
END $$;

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN CREATE ROLE service_role NOLOGIN BYPASSRLS; END IF;
END $$;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE SCHEMA IF NOT EXISTS storage;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
CREATE TABLE auth.users (id uuid PRIMARY KEY, email text);
CREATE OR REPLACE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT (string_to_array(name, '/'))[1:array_length(string_to_array(name, '/'), 1) - 1]
$$;
GRANT USAGE ON SCHEMA auth, storage, public TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION storage.foldername(text) TO anon, authenticated, service_role;

CREATE TABLE public.organizations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text, type text,
  created_at timestamptz DEFAULT now(),
  created_by uuid,
  list_in_directory boolean DEFAULT false,
  storefront_enabled boolean DEFAULT false,
  logo_url text
);
CREATE TABLE public.organization_memberships (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id uuid NOT NULL, organization_id bigint NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  role text, is_home boolean DEFAULT false, created_at timestamptz DEFAULT now()
);
CREATE TABLE public.organization_customers (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  service_organization_id bigint NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  customer_organization_id bigint NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(),
  notes text, created_by uuid,
  CONSTRAINT organization_customers_unique UNIQUE (service_organization_id, customer_organization_id)
);
CREATE TABLE public.user_profiles (id uuid PRIMARY KEY, organization_id bigint, active_organization_id bigint);
CREATE TABLE public.engineer_invitations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint, email text, role text, accepted boolean DEFAULT false,
  expires_at timestamptz, created_at timestamptz DEFAULT now(), invited_by uuid
);
CREATE TABLE public.equipment (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_organization_id bigint, serial_number text, name text
);
CREATE TABLE public.contacts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id bigint, name text);
CREATE TABLE public.locations (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id bigint, name text);
CREATE TABLE public.service_reports (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint, customer_organization_id bigint, equipment_id bigint,
  serial_number text, created_by uuid
);

-- Live function definitions (before 000916).
CREATE OR REPLACE FUNCTION public.is_active_org_member(p_org bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_memberships m
    WHERE m.user_id = auth.uid()
      AND m.organization_id = p_org
  );
$function$;

CREATE OR REPLACE FUNCTION public.auth_member_of_org(org_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT org_id IS NOT NULL
    AND auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.organization_memberships m
      WHERE m.user_id = auth.uid()
        AND m.organization_id = org_id
    );
$function$;

CREATE OR REPLACE FUNCTION public.get_my_org_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    (
      SELECT p.active_organization_id
      FROM public.user_profiles p
      WHERE p.id = auth.uid()
        AND p.active_organization_id IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.organization_memberships m
          WHERE m.user_id = auth.uid()
            AND m.organization_id = p.active_organization_id
        )
      LIMIT 1
    ),
    (
      SELECT m.organization_id
      FROM public.organization_memberships m
      WHERE m.user_id = auth.uid()
      ORDER BY m.is_home DESC NULLS LAST, m.created_at ASC NULLS LAST
      LIMIT 1
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.auth_login_email()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT NULLIF(lower(btrim(u.email)), '')
  FROM auth.users AS u
  WHERE u.id = auth.uid();
$function$;

CREATE OR REPLACE FUNCTION public.invitation_is_open(p_accepted boolean, p_expires_at timestamp with time zone, p_created_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(p_accepted, false) = false
    AND (
      (p_expires_at IS NOT NULL AND p_expires_at > now())
      OR (
        p_expires_at IS NULL
        AND p_created_at IS NOT NULL
        AND p_created_at > (now() - interval '14 days')
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.profile_role_from_membership(p_role text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN lower(btrim(coalesce(p_role, ''))) = 'admin' THEN 'company_admin'
    WHEN nullif(btrim(p_role), '') IS NULL THEN 'fse'
    ELSE btrim(p_role)
  END;
$function$;

CREATE OR REPLACE FUNCTION public.founder_role_for_org(p_organization_id bigint)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE lower(btrim(coalesce(o.type, '')))
    WHEN 'parts_supplier' THEN 'parts_supplier'
    WHEN 'supplier' THEN 'parts_supplier'
    WHEN 'vendor' THEN 'parts_supplier'
    WHEN 'customer' THEN 'owner'
    WHEN 'laser_clinic' THEN 'owner'
    WHEN 'laser_rental' THEN 'owner'
    WHEN 'laser_reseller' THEN 'owner'
    WHEN 'service_company' THEN 'company_admin'
    ELSE 'company_admin'
  END
  FROM public.organizations o
  WHERE o.id = p_organization_id;
$function$;

CREATE OR REPLACE FUNCTION public.storage_org_id_from_name(object_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  parts text[];
  candidate text;
BEGIN
  IF object_name IS NULL OR btrim(object_name) = '' THEN
    RETURN NULL;
  END IF;
  parts := storage.foldername(object_name);
  IF parts IS NULL OR array_length(parts, 1) IS NULL THEN
    RETURN NULL;
  END IF;
  IF parts[1] = 'equipment' AND array_length(parts, 1) >= 2 THEN
    candidate := parts[2];
  ELSE
    candidate := parts[1];
  END IF;
  IF candidate ~ '^[0-9]+$' THEN
    RETURN candidate::bigint;
  END IF;
  RETURN NULL;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.user_owns_or_created_org(org_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    org_id IS NOT NULL
    AND (
      (
        org_id = public.get_my_org_id()
        AND public.is_active_org_member(org_id)
      )
      OR EXISTS (
        SELECT 1
        FROM public.organizations o
        WHERE o.id = org_id
          AND o.created_by = auth.uid()
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.membership_insert_allowed(p_user_id uuid, p_organization_id bigint, p_role text, p_is_home boolean)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_user_id IS NOT DISTINCT FROM auth.uid()
    AND (
      (
        EXISTS (
          SELECT 1 FROM public.organizations o
          WHERE o.id = p_organization_id AND o.created_by = auth.uid()
        )
        AND lower(btrim(coalesce(p_role, ''))) IN (
          public.founder_role_for_org(p_organization_id),
          'fse', 'engineer', 'technician'
        )
        AND lower(btrim(coalesce(p_role, ''))) <> 'admin'
      )
      OR (
        COALESCE(p_is_home, false) = false
        AND lower(btrim(coalesce(p_role, ''))) <> 'admin'
        AND EXISTS (
          SELECT 1 FROM public.engineer_invitations i
          WHERE i.organization_id = p_organization_id
            AND public.auth_login_email() IS NOT NULL
            AND lower(btrim(i.email)) = public.auth_login_email()
            AND public.invitation_is_open(i.accepted, i.expires_at, i.created_at)
            AND lower(btrim(coalesce(p_role, ''))) = public.profile_role_from_membership(
              coalesce(NULLIF(TRIM(i.role), ''), 'fse')
            )
        )
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.profile_org_change_allowed(p_org bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET row_security TO 'off'
AS $function$
  SELECT p_org IS NULL
    OR EXISTS (
      SELECT 1 FROM public.organizations o
      WHERE o.id = p_org AND o.created_by = auth.uid()
    )
    OR EXISTS (
      SELECT 1 FROM public.organization_memberships m
      WHERE m.user_id = auth.uid() AND m.organization_id = p_org
    )
    OR EXISTS (
      SELECT 1 FROM public.engineer_invitations i
      WHERE i.organization_id = p_org
        AND public.auth_login_email() IS NOT NULL
        AND lower(btrim(i.email)) = public.auth_login_email()
        AND public.invitation_is_open(i.accepted, i.expires_at, i.created_at)
    );
$function$;

CREATE OR REPLACE FUNCTION public.logo_object_readable(object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  org_id bigint;
  published boolean := false;
BEGIN
  org_id := public.storage_org_id_from_name(object_name);
  IF org_id IS NULL OR auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF public.auth_member_of_org(org_id) THEN
    RETURN true;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.organizations o
    WHERE o.id = org_id
      AND o.created_by = auth.uid()
  ) THEN
    RETURN true;
  END IF;

  IF to_regclass('public.organization_customers') IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_customers oc
    WHERE oc.customer_organization_id = org_id
      AND public.auth_member_of_org(oc.service_organization_id)
  ) THEN
    RETURN true;
  END IF;

  BEGIN
    EXECUTE
      'SELECT (COALESCE(o.list_in_directory, false) OR COALESCE(o.storefront_enabled, false))
         AND o.logo_url IS NOT NULL
         AND position($2 in o.logo_url) > 0
       FROM public.organizations o
       WHERE o.id = $1'
      INTO published
      USING org_id, object_name;
  EXCEPTION WHEN undefined_column THEN
    BEGIN
      EXECUTE
        'SELECT COALESCE(o.list_in_directory, false)
           AND o.logo_url IS NOT NULL
           AND position($2 in o.logo_url) > 0
         FROM public.organizations o
         WHERE o.id = $1'
        INTO published
        USING org_id, object_name;
    EXCEPTION WHEN undefined_column THEN
      published := false;
    END;
  END;

  RETURN COALESCE(published, false);
END;
$function$;

CREATE OR REPLACE FUNCTION public.can_view_service_report_for_history(r service_reports)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    -- Own service company reports
    (r.organization_id IS NOT NULL AND r.organization_id = public.get_my_org_id())
    OR (
      r.created_by IS NOT NULL
      AND r.created_by = auth.uid()
      AND public.is_active_org_member(r.organization_id)
    )
    -- Facility that is the report customer
    OR (
      r.customer_organization_id IS NOT NULL
      AND public.user_owns_or_created_org(r.customer_organization_id)
    )
    -- Facility that currently owns the linked equipment row
    OR (
      r.equipment_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.equipment e
        WHERE e.id = r.equipment_id
          AND public.user_owns_or_created_org(e.customer_organization_id)
      )
    )
    -- Facility that currently owns a laser with the same serial (transfer case)
    OR (
      r.serial_number IS NOT NULL
      AND trim(r.serial_number) <> ''
      AND EXISTS (
        SELECT 1 FROM public.equipment e
        WHERE e.serial_number IS NOT NULL
          AND lower(trim(e.serial_number)) = lower(trim(r.serial_number))
          AND public.user_owns_or_created_org(e.customer_organization_id)
      )
    )
    -- Service org linked via organization_customers to report customer
    OR (
      r.customer_organization_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.organization_customers oc
        WHERE oc.customer_organization_id = r.customer_organization_id
          AND oc.service_organization_id = public.get_my_org_id()
      )
    );
$function$;

REVOKE ALL ON FUNCTION public.user_owns_or_created_org(bigint), public.membership_insert_allowed(uuid, bigint, text, boolean),
  public.profile_org_change_allowed(bigint), public.logo_object_readable(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.user_owns_or_created_org(bigint), public.membership_insert_allowed(uuid, bigint, text, boolean),
  public.profile_org_change_allowed(bigint), public.logo_object_readable(text) TO authenticated, service_role;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO authenticated, service_role;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO authenticated, service_role;

ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organization_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organization_customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.equipment ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.service_reports ENABLE ROW LEVEL SECURITY;

-- Live policies (pg_policies, 2026-10-11).
CREATE POLICY "Authenticated users can insert organizations" ON public.organizations FOR INSERT TO authenticated
  WITH CHECK ((created_by = auth.uid()) OR (created_by IS NULL));
CREATE POLICY "Users can delete their own organizations" ON public.organizations FOR DELETE TO authenticated
  USING (created_by = auth.uid());
CREATE POLICY "Users can update their own organizations" ON public.organizations FOR UPDATE TO authenticated
  USING (created_by = auth.uid());
CREATE POLICY organizations_crm_customer_select ON public.organizations FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM organization_customers oc
    WHERE oc.customer_organization_id = organizations.id AND auth_member_of_org(oc.service_organization_id)));
CREATE POLICY organizations_member_select ON public.organizations FOR SELECT TO authenticated
  USING (auth_member_of_org(id) OR (created_by = auth.uid()));
CREATE POLICY organizations_published_select ON public.organizations FOR SELECT TO authenticated
  USING (COALESCE(list_in_directory, false) = true);

CREATE POLICY organization_memberships_insert_own_home ON public.organization_memberships FOR INSERT TO authenticated
  WITH CHECK (membership_insert_allowed(user_id, organization_id, role, is_home));
CREATE POLICY organization_memberships_select_own ON public.organization_memberships FOR SELECT TO authenticated
  USING (user_id = auth.uid());

CREATE POLICY oc_select ON public.organization_customers FOR SELECT TO authenticated
  USING (is_active_org_member(service_organization_id));

CREATE POLICY equipment_facility_manage ON public.equipment FOR ALL TO authenticated
  USING (user_owns_or_created_org(customer_organization_id))
  WITH CHECK (user_owns_or_created_org(customer_organization_id));
CREATE POLICY equipment_member_select ON public.equipment FOR SELECT TO authenticated
  USING (auth_member_of_org(customer_organization_id));
CREATE POLICY equipment_service_org_manage ON public.equipment FOR ALL TO authenticated
  USING (user_owns_or_created_org(customer_organization_id) OR (EXISTS (SELECT 1
    FROM (organization_customers oc JOIN user_profiles up ON ((up.organization_id = oc.service_organization_id)))
    WHERE ((up.id = auth.uid()) AND (oc.customer_organization_id = equipment.customer_organization_id) AND is_active_org_member(oc.service_organization_id)))))
  WITH CHECK (user_owns_or_created_org(customer_organization_id) OR (EXISTS (SELECT 1
    FROM (organization_customers oc JOIN user_profiles up ON ((up.organization_id = oc.service_organization_id)))
    WHERE ((up.id = auth.uid()) AND (oc.customer_organization_id = equipment.customer_organization_id) AND is_active_org_member(oc.service_organization_id)))));
CREATE POLICY contacts_service_company_linked_manage ON public.contacts FOR ALL TO authenticated
  USING (user_owns_or_created_org(organization_id) OR (EXISTS (SELECT 1 FROM organization_customers oc
    WHERE ((oc.customer_organization_id = contacts.organization_id) AND (oc.service_organization_id = get_my_org_id())))))
  WITH CHECK (user_owns_or_created_org(organization_id) OR (EXISTS (SELECT 1 FROM organization_customers oc
    WHERE ((oc.customer_organization_id = contacts.organization_id) AND (oc.service_organization_id = get_my_org_id())))));
CREATE POLICY locations_service_company_linked_manage ON public.locations FOR ALL TO authenticated
  USING (user_owns_or_created_org(organization_id) OR (EXISTS (SELECT 1 FROM organization_customers oc
    WHERE ((oc.customer_organization_id = locations.organization_id) AND (oc.service_organization_id = get_my_org_id())))))
  WITH CHECK (user_owns_or_created_org(organization_id) OR (EXISTS (SELECT 1 FROM organization_customers oc
    WHERE ((oc.customer_organization_id = locations.organization_id) AND (oc.service_organization_id = get_my_org_id())))));
CREATE POLICY service_reports_equipment_history_select ON public.service_reports FOR SELECT TO authenticated
  USING (can_view_service_report_for_history(service_reports.*));

