-- Rows one user sees for customer org p_org under RLS:
-- [org row, equipment, contacts, locations, service reports].
CREATE FUNCTION pg_temp.seen(p_user uuid, p_org bigint) RETURNS int[] LANGUAGE plpgsql AS $$
DECLARE r int[];
BEGIN
  PERFORM set_config('request.jwt.claim.sub', p_user::text, true);
  PERFORM set_config('role', 'authenticated', true);
  SELECT ARRAY[
    (SELECT count(*) FROM public.organizations WHERE id = p_org),
    (SELECT count(*) FROM public.equipment WHERE customer_organization_id = p_org),
    (SELECT count(*) FROM public.contacts WHERE organization_id = p_org),
    (SELECT count(*) FROM public.locations WHERE organization_id = p_org),
    (SELECT count(*) FROM public.service_reports WHERE customer_organization_id = p_org)
  ]::int[] INTO r;
  PERFORM set_config('role', 'postgres', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  RETURN r;
END $$;

-- Rows one user's UPDATEs touch: [org row, equipment, contacts, locations].
CREATE FUNCTION pg_temp.writes(p_user uuid, p_org bigint) RETURNS int[] LANGUAGE plpgsql AS $$
DECLARE a int; b int; c int; d int;
BEGIN
  PERFORM set_config('request.jwt.claim.sub', p_user::text, true);
  PERFORM set_config('role', 'authenticated', true);
  UPDATE public.organizations SET name = name WHERE id = p_org; GET DIAGNOSTICS a = ROW_COUNT;
  UPDATE public.equipment SET name = name WHERE customer_organization_id = p_org; GET DIAGNOSTICS b = ROW_COUNT;
  UPDATE public.contacts SET name = name WHERE organization_id = p_org; GET DIAGNOSTICS c = ROW_COUNT;
  UPDATE public.locations SET name = name WHERE organization_id = p_org; GET DIAGNOSTICS d = ROW_COUNT;
  PERFORM set_config('role', 'postgres', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  RETURN ARRAY[a, b, c, d];
END $$;

-- Probe an INSERT as a user; the probe row is always undone.
CREATE FUNCTION pg_temp.can_insert(p_user uuid, p_sql text) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE ok boolean;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claim.sub', p_user::text, true);
    PERFORM set_config('role', 'authenticated', true);
    EXECUTE p_sql;
    RAISE EXCEPTION 'undo probe' USING ERRCODE = 'P0001';
  EXCEPTION
    WHEN insufficient_privilege THEN ok := false;
    WHEN raise_exception THEN ok := true;
  END;
  PERFORM set_config('role', 'postgres', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  RETURN ok;
END $$;

CREATE FUNCTION pg_temp.as_user_bool(p_user uuid, p_sql text) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE r boolean;
BEGIN
  PERFORM set_config('request.jwt.claim.sub', p_user::text, true);
  PERFORM set_config('role', 'authenticated', true);
  EXECUTE p_sql INTO r;
  PERFORM set_config('role', 'postgres', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  RETURN r;
END $$;

